float rad2b = abs(abs(uv1.x)-abs(uv1.y)) / 1.0; //4 Tuerme
rad2 = abs(rad2b*uv1.x)*q30;
vec2 uv2 = vec2 (ang1/3.14, 1.0 / rad2);
vec2 uvm = uv2 ;
uvm.y = uv2.y / 8.0 + q9;
uvm.x = uv2.x;
vec3 crisp = texture(sampler_main,uvm);
vec3 blur = GetBlur1(fract(uvm - .0*crisp));
vec3 ret1c = crisp;
vec3 ret1b = (blur);
//*****************
vec2 uv4 = 64.0 * (multiply(uv,mat2(.6,.8,-.8,.6))+uTime / 64.0);
vec3 smask = (texture(sampler_pw_noise_lq,uv4 / 256.0)).g-.9;
float stars = clamp01(.5/length(abs(fract(uv4)-.5))*smask);
float moon = clamp01(.01/length(uv1));
