float mask_b = clamp01(2.0 / pow(uv2.y, 1.0 ));
vec3 ret1 = ret1c * mask_c + ret1b * mask_b;
ret = ret1  + 0.2 * clamp01(.05/ (mask_c+.1))*vec3 ( 0.0 , 0.0 , 1.0 )
+ clamp01((stars * stars +moon) * 1.0-mask_c * 16.0);
}

